package com.example.shortener.feature.link.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="clicks") public class Click { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private LocalDateTime clickedAt=LocalDateTime.now(); private String ip,country,city,userAgent; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="link_id",nullable=false) private ShortLink shortLink; public Click(){} public Click(String ip,String ua,String country,String city,ShortLink link){this.ip=ip;this.userAgent=ua;this.country=country;this.city=city;this.shortLink=link;} public LocalDateTime getClickedAt(){return clickedAt;} public String getIp(){return ip;} public String getCountry(){return country;} public String getCity(){return city;} }
